  KEY `idx_prod_plan_code_single` (`prod_plan_code`),
  KEY `idx_prod_sub_id_single` (`prod_sub_id`),
  KEY `idx_route_code_single` (`route_code`),
  KEY `idx_sale_order_code_single` (`sale_order_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='月排订单表';

-- mes_aps_month_schedule
CREATE TABLE `mes_aps_month_schedule` (
