-- mes_aps_purchase_plan
CREATE TABLE `mes_aps_purchase_plan` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '编码',
  `is_check` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '10' COMMENT '审核状态10=未审核，20=已审核',
  `prch_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '类别0面向库存1面向订单',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '部门',
  `apl_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '申请人',
  `apl_tm` datetime DEFAULT NULL COMMENT '申请时间',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '提交人',
  `crt_tm` datetime DEFAULT NULL COMMENT '提交时间',
  `check_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '审核人',
  `check_tm` datetime DEFAULT NULL COMMENT '审核时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '更新人',
  `upd_tm` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新日期',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注',
  `sale_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单编码',
  `material_plan_code` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料需求计划主表CODE',
  `material_plan_id` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '物料需求计划主表ID',
  `status` tinyint DEFAULT '0' COMMENT '流程状态:0草稿,1审核中,2已通过,3已驳回,4撤回,5终止',
  `production_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `prod_plan_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划编码',
  `prod_pln_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划行号',
  `del_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '删除人ID',
  `del_tm` datetime DEFAULT NULL COMMENT '删除日期',
  `delete_mark` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '删除标志(0-未删，1-已删除)',
  `enabled_mark` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '有效标志(0-禁用，1-启用)',
  `sort_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '排序',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_prod_plan_code_single` (`prod_plan_code`),
  KEY `idx_prod_pln_sub_code_single` (`prod_pln_sub_code`),
  KEY `idx_production_order_code_single` (`production_order_code`),
  KEY `idx_sale_order_code_single` (`sale_order_code`),
  KEY `idx_sort_code_single` (`sort_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='排产-采购计划';

-- mes_aps_purchase_plan_sub
