  KEY `pd_code` (`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_mid_single` (`mid`),
  KEY `idx_pd_code_single` (`pd_code`),
  KEY `idx_sort_code_single` (`sort_code`),
  KEY `idx_splr_code_single` (`splr_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='排产-采购计划明细';

