-- mes_aps_week_schedule
CREATE TABLE `mes_aps_week_schedule` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键ID',
  `book_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套ID',
  `week_config_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '周排产配置ID',
  `plan_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划子表ID',
  `day` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '日期',
  `line_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产线编号',
  `material_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编号',
  `count` decimal(10,2) DEFAULT NULL COMMENT '排产数量',
  `product_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产品编号（冗余）',
  `has_overload` tinyint DEFAULT NULL COMMENT '是否超负荷（1：是，0：否）',
  `has_overdue` tinyint DEFAULT NULL COMMENT '是否逾期（1：是，0：否）',
  `has_product_line` tinyint DEFAULT NULL COMMENT '是否产品产线（1：是，0：否）',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '更新人',
  `upd_tm` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '删除人',
  `del_tm` datetime DEFAULT NULL COMMENT '删除时间',
  `delete_mark` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志(0-未删，1-已删除)',
  PRIMARY KEY (`id`,`book_id`),
  KEY `idx_line_code_single` (`line_code`),
  KEY `idx_material_code_single` (`material_code`),
  KEY `idx_plan_code_single` (`plan_code`),
  KEY `idx_product_code_single` (`product_code`),
  KEY `idx_week_config_id_single` (`week_config_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='周排产结果表';

