-- mes_bom
CREATE TABLE `mes_bom` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'ID',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '行号',
  `check_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '审核状态:10未审核20已审核',
  `mate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编码',
  `bom_ver` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `bom_ver_cmnt` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '版本说明',
  `pcs_mode` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '加工方式:10车削20铣削30铸造40热处理50冲压60电镀',
  `parent_loss_rate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '母件损耗率',
  `eff_dt` date DEFAULT NULL COMMENT '版本生效日期',
  `sort` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '排序号',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `upd_tm` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注',
  `check_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '审核人',
  `check_tm` datetime DEFAULT NULL COMMENT '审核时间',
  `hasChildren` tinyint DEFAULT '0' COMMENT '有无下级',
  `hasChildrenCount` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '0' COMMENT '下级数量',
  `pid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '父级节点',
  `mate_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料ID',
  `spec_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '计量单位',
  `version` int DEFAULT NULL COMMENT '版本号',
  `mate_quality` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '材质',
  `figure_nbr` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '图号',
  `nature` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料性质:1原材料2半成品3成品',
  `mode` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '加工方式:1自制2外协3外购',
  `quantity` decimal(10,6) DEFAULT NULL COMMENT '数量',
  `batch_nbr` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '批次号',
  `sort_nbr` int DEFAULT NULL COMMENT '排序号',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工位名称',
  `operat_route` varchar(255) DEFAULT NULL COMMENT '操作工艺',
  `requirement` varchar(255) DEFAULT NULL COMMENT '指标要求',
  `status` varchar(5) DEFAULT NULL COMMENT '审批流：0草稿,1审核中,2已通过,3已驳回,4已撤回,5已终止\r\n状态切换：0草稿,1待审核,2已审核',
  `mate_attr` varchar(5) DEFAULT NULL COMMENT '物料属性',
  `pvdr_code` varchar(50) DEFAULT NULL COMMENT '供应商编码',
  `design_uid` varchar(50) DEFAULT NULL COMMENT '设计员id',
  `design_type` varchar(5) DEFAULT NULL COMMENT '设计类型',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_mate_id_single` (`mate_id`),
  KEY `idx_pvdr_code_single` (`pvdr_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='BOM管理';

