  `sub_replace_way` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '0-无替代/1-部分替代/2-全部替代/3-全部+部分替代',
  `unit_prc` decimal(50,0) DEFAULT NULL COMMENT '物料单价',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_design_code_single` (`design_code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_mid_single` (`mid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='生产BOM明细子表';

-- mes_completion_order
CREATE TABLE `mes_completion_order` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'id',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '完工单编号',
  `make_st` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请状态:10未申请20部分申请30已申请',
  `production_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `prod_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产工单编码',
  `mate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编码',
  `prod_order_qty` decimal(10,2) DEFAULT NULL COMMENT '生产工单数量',
  `elig_qty` decimal(10,2) DEFAULT NULL COMMENT '合格量',
  `maked_qty` decimal(10,2) DEFAULT NULL COMMENT '已申请数量',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `upd_tm` datetime DEFAULT NULL COMMENT '修改时间',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注信息',
  `define1` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '自定义项1',
  `define2` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '自定义项2',
  `define3` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '自定义项3',
  `define4` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '自定义项4',
  `define5` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '自定义项5',
  `inbound_qty` decimal(10,2) DEFAULT NULL COMMENT '入库数量',
  `production_qty` decimal(10,2) DEFAULT NULL COMMENT '生产订单数量',
  `production_order_sub_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单明细id',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '部门编码',
  `line_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产线编码',
  `act_com_time` datetime DEFAULT NULL COMMENT '实际完工时间',
  `outsource_order_sub_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '外协订单明细id',
  `aux_unit` varchar(50) DEFAULT NULL COMMENT '生产单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '生产数量',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_line_code_single` (`line_code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_outsource_order_sub_id_single` (`outsource_order_sub_id`),
  KEY `idx_prod_order_code_single` (`prod_order_code`),
  KEY `idx_production_order_code_single` (`production_order_code`),
  KEY `idx_production_order_sub_id_single` (`production_order_sub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='完工单';

