-- mes_job_task_order
CREATE TABLE `mes_job_task_order` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `mid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '主表id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '作业任务单编号',
  `finish_st` int DEFAULT NULL COMMENT '状态:5暂停中10未开始12进行中15部分完成20已完成',
  `pcs_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工序名称',
  `mate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编码',
  `output_mate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产出物编码',
  `rgon_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '车间',
  `plant_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '设备',
  `team_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '班组',
  `oprl_uid` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '作业人',
  `pln_start_tm` datetime DEFAULT NULL COMMENT '计划开始时间',
  `pln_end_tm` datetime DEFAULT NULL COMMENT '计划结束时间',
  `stn_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工位',
  `qty` decimal(10,2) DEFAULT NULL COMMENT '加工数量',
  `finish_tm` datetime DEFAULT NULL COMMENT '完工时间',
  `piece_rate` decimal(10,2) DEFAULT NULL COMMENT '工资/件',
  `sort` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '排序号',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注信息',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建用户',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改用户',
  `upd_tm` datetime DEFAULT NULL COMMENT '修改时间',
  `is_urgent` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否加急=0否1是',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产部门',
  `finished_qty` decimal(10,2) DEFAULT NULL COMMENT '已报工数量',
  `production_work_order_sub_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产工单明细id',
  `production_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `prod_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产工单编码',
  `line_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产线编码',
  `act_start_tm` datetime DEFAULT NULL COMMENT '实际开工时间',
  `act_end_tm` datetime DEFAULT NULL COMMENT '实际完工时间',
  `last_start_tm` datetime DEFAULT NULL COMMENT '末次开工时间',
  `rated_hour` decimal(10,2) DEFAULT '0.00' COMMENT '额定工时',
  `act_hour` decimal(10,2) DEFAULT '0.00' COMMENT '实际工时',
  `batch_no` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '批次号',
  `is_outsource` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否外协 0：否 1：是',
  `production_mode` varchar(5) DEFAULT NULL COMMENT '是否包料',
  `pvdr_code` varchar(50) DEFAULT NULL COMMENT '加工商名称',
  `out_type` varchar(5) DEFAULT NULL COMMENT '委外类型',
  `sett_fee` decimal(10,2) DEFAULT NULL COMMENT '结算费用',
  `rqm_dt` date DEFAULT NULL,
  `mate_cost` decimal(10,2) DEFAULT NULL COMMENT '材料费用',
  `check_uid` varchar(50) DEFAULT NULL COMMENT '审核人',
  `check_tm` datetime DEFAULT NULL COMMENT '审核时间',
  `status` varchar(5) DEFAULT NULL COMMENT '审核状态',
  `production_order_sub_id` varchar(50) DEFAULT NULL COMMENT '生产订单明细ID',
  `change_st` varchar(10) DEFAULT '10' COMMENT '变更状态:10正常20锁定30已变更40终止',
  `lock_src_id` varchar(50) DEFAULT NULL COMMENT '上游变更申请id',
  `aux_unit` varchar(50) DEFAULT NULL COMMENT '生产单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '生产数量',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_batch_no_single` (`batch_no`),
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_line_code_single` (`line_code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_mid_single` (`mid`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_output_mate_code_single` (`output_mate_code`),
  KEY `idx_pcs_code_single` (`pcs_code`),
  KEY `idx_plant_code_single` (`plant_code`),
  KEY `idx_prod_order_code_single` (`prod_order_code`),
  KEY `idx_production_order_code_single` (`production_order_code`),
  KEY `idx_production_work_order_sub_id_single` (`production_work_order_sub_id`),
  KEY `idx_rgon_code_single` (`rgon_code`),
  KEY `idx_stn_code_single` (`stn_code`),
  KEY `idx_team_code_single` (`team_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='作业任务单';

-- mes_job_task_suspend_hours
CREATE TABLE `mes_job_task_suspend_hours` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'id',
  `book_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'NULL' COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '编码',
  `job_task_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '作业任务单编码',
  `st` int DEFAULT NULL COMMENT '状态:5=暂停, 12=进行中',
  `suspend_start_tm` datetime DEFAULT NULL COMMENT '暂停开始时间',
  `suspend_end_tm` datetime DEFAULT NULL COMMENT '暂停结束时间',
  `suspend_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '暂停人',
  `recovery_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '恢复人',
  `suspend_reason` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '暂停原因',
  `report_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '报工单编码',
  `suspend_duration` decimal(10,2) DEFAULT NULL COMMENT '暂停时长',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注信息',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `upd_tm` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`,`book_id`),
  KEY `idx_code_single` (`code`),
  KEY `idx_job_task_code_single` (`job_task_code`),
  KEY `idx_report_order_code_single` (`report_order_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='作业任务暂停工时表';

-- mes_outsource_order
CREATE TABLE `mes_outsource_order` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '外协订单编码',
