  `production_order_code` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `prod_plan_code` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划编码',
  `aps_plan_code` varchar(100) DEFAULT NULL COMMENT '物料需求计划编码',
  `status` varchar(5) DEFAULT NULL COMMENT '审批状态',
