  KEY `idx_prod_plan_code_single` (`prod_plan_code`),
  KEY `idx_production_order_code_single` (`production_order_code`),
  KEY `idx_provider_code_single` (`provider_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='外协订单';

-- mes_outsource_order_old
CREATE TABLE `mes_outsource_order_old` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '外协订单编码',
  `mate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编码',
  `bom_ver` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `qty` decimal(10,2) DEFAULT NULL COMMENT '数量',
  `mate_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料类别:10原材料、20半成品、30成品',
  `production_mode` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产方式 0：包工包料  1：带料加工',
  `provider_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '委外供应商code',
  `require_dt` date DEFAULT NULL COMMENT '要货日期',
  `carry_st` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '10' COMMENT '执行状态：10待执行、20执行中、30已执行',
  `plan_order_sub_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划明细id',
  `production_order_sub_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单明细id',
  `is_finish_pd_check` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否成品检 0：否 1：是',
  `inspect_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '检验方案编码(is_finish_pd_check为1时必填)',
  `act_com_time` timestamp NULL DEFAULT NULL COMMENT '实际结束时间',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '更新人',
  `upd_tm` datetime DEFAULT NULL COMMENT '更新时间',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '部门编码',
  `remarks` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注',
  `is_inspection` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否报检 0：否 1：是',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `crt_tm` (`crt_tm`) USING BTREE,
  KEY `code` (`code`) USING BTREE,
  KEY `crt_uid` (`crt_uid`) USING BTREE,
  KEY `mate_code` (`mate_code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='外协订单';

