  `inspect_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '检验方案编码(is_finish_pd_check为1时必填)',
  `act_com_time` timestamp NULL DEFAULT NULL COMMENT '实际结束时间',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '更新人',
  `upd_tm` datetime DEFAULT NULL COMMENT '更新时间',
  `remarks` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注',
  `is_inspection` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否报检 0：否 1：是',
  `aps_plan_sub_code` varchar(50) DEFAULT NULL COMMENT 'APS计划子表编码',
  `aps_plan_sub_id` varchar(50) DEFAULT NULL COMMENT 'APS计划子表编码',
  `month_plan_id` varchar(50) DEFAULT NULL COMMENT '月计划ID',
  `mate_cont` decimal(10,2) DEFAULT NULL COMMENT '材料费',
  `out_fee` decimal(10,2) DEFAULT NULL COMMENT '加工费',
  `out_type` varchar(5) DEFAULT NULL COMMENT '物料委外10、产能委外20',
  `aux_unit` varchar(50) DEFAULT NULL COMMENT '生产单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '生产数量',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_aps_plan_sub_code_single` (`aps_plan_sub_code`),
  KEY `idx_aps_plan_sub_id_single` (`aps_plan_sub_id`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_inspect_code_single` (`inspect_code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_mid_single` (`mid`),
  KEY `idx_month_plan_id_single` (`month_plan_id`),
  KEY `idx_plan_order_sub_id_single` (`plan_order_sub_id`),
  KEY `idx_production_order_sub_id_single` (`production_order_sub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='外协订单';

-- mes_produce_order
CREATE TABLE `mes_produce_order` (
