  `mod_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '变更类型0=正常,1=已变更,2=已取消,3=已暂停,4=已恢复',
  `pid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '机加数据父ID',
  `prod_pln_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划行号',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '加工部门01=工控事业部,02=工业互联事业部,03=空调事业部,04=数字机加,06=灯具开关',
  `is_urgent` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否加急=0否1是',
  `make_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生成入库单状态:10未生成20已生成',
  `sale_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单编码',
  `drawing_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '图号',
  `product_plan_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单子表行号',
  `crm_sale_order_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '客户订单编码',
  `md_mate_info_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编码',
  `product_msr` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '派工数量',
  `completed_quantity` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '完工数量',
  `team_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '报工班组',
  `finish_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否完工',
  `finish_dt` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '完工日期',
  `urgent_type` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '紧急程度',
  `duty_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '责任人',
  `md_mate_info_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料ID',
  `md_mate_info_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料名称',
  `mate_unit_type_enCode` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '核算类型英文编码',
  `mate_unit_type_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '核算类型(重量、数量)',
  `spec_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '规格型号',
  `total_msr` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '总计重量(KG)',
  `unit` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '计量单位',
  `unit_prc` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '单价(元)',
  `unit_kg` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '单重(KG)',
  `piece_prc` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '计件工资(元)',
  `mode` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '加工方式:1自制2外协3外购',
  `output_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产出物编码',
  `region_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '车间',
  `plant_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '设备',
  `operator` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '作业人',
  `plan_start_dt` date DEFAULT NULL,
  `plan_end_dt` date DEFAULT NULL,
  `region_station` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工位',
  `proc_flow_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工艺名称',
  `proc_flow_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工艺流转方向',
  `production_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `line_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产线名称',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crm_sale_order_sub_code_single` (`crm_sale_order_sub_code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_md_mate_info_code_single` (`md_mate_info_code`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_prod_pln_sub_code_single` (`prod_pln_sub_code`),
  KEY `idx_product_plan_sub_code_single` (`product_plan_sub_code`),
  KEY `idx_route_code_single` (`route_code`),
  KEY `idx_sale_order_code_single` (`sale_order_code`),
  KEY `idx_team_id_single` (`team_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='生产工单';

