  KEY `idx_crm_sale_order_sub_code_single` (`crm_sale_order_sub_code`),
  KEY `idx_md_mate_info_code_single` (`md_mate_info_code`),
  KEY `idx_md_mate_info_id_single` (`md_mate_info_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='生产工单子表';

-- mes_production_batch_bind
