-- mes_production_order
CREATE TABLE `mes_production_order` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '编码',
  `sale_order_code` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '销售订单编码',
  `check_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '审批状态=0未审批1已审批',
  `presale_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '售前单号',
  `cust_level` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '客户等级:10A,20B,30C',
  `urgent_level` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '紧急程度:10一般,20紧急,30特急',
  `rqm_dt` date DEFAULT NULL COMMENT '需求日期',
  `tech_level` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '技术等级:10A,20S',
  `check_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '审批人',
  `check_tm` datetime DEFAULT NULL COMMENT '审批时间',
  `file` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '订单附件',
  `prep_info` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '资料准备:10配防爆合格证,20说明书,30检测报告,40出厂合格证,50装箱清单',
  `remarks` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `crt_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '更新人',
  `upd_tm` datetime DEFAULT NULL COMMENT '更新时间',
  `presale_tech` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '售前技术',
  `nature` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '10' COMMENT '计划类别10=订单,20=备货,30=售后',
  `is_urgent` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否加急=0否1是',
  `define1` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '自定义1',
  `status` tinyint DEFAULT NULL COMMENT '流程状态:0草稿,1审核中,2已通过,3已驳回,4撤回,5终止',
  `presale_no` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '售前单号',
  `cust_cate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '客户等级1A2B3C',
  `urgent_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '紧急状态1一般2加急3特急',
  `need_dt` date DEFAULT NULL COMMENT '交货日期',
  `technical_cate` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '技术等级1A 2S',
  `check_person` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '审批人',
  `check_dt` date DEFAULT NULL,
  `material` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '资料准备:1配防爆合格证2说明书3检测报告4出厂合格证5装箱清单',
  `order_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单类型：10生产订单',
  `salesman` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '业务员',
  `order_dt` date DEFAULT NULL,
  `customer_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '客户名称',
  `is_finish` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否完成',
  `is_snd` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '是否发货0=未发货,1=已发货',
  `prod_plan_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划编码',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '部门',
  `act_hour` decimal(10,2) DEFAULT NULL COMMENT '实际工时',
  `rated_hour` decimal(10,2) DEFAULT NULL COMMENT '额定工时',
  `aps_plan_code` varchar(100) DEFAULT NULL COMMENT '物料需求计划编码',
  `change_st` varchar(10) DEFAULT '10' COMMENT '变更状态:10正常20锁定30已变更40终止',
  `lock_src_id` varchar(50) DEFAULT NULL COMMENT '上游变更申请id',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_presale_code_single` (`presale_code`),
  KEY `idx_presale_no_single` (`presale_no`),
  KEY `idx_prod_plan_code_single` (`prod_plan_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='生产订单';

-- mes_production_order_sub
