  `new_pd_logo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '新产品标识1=A,2=B,3=C',
  `team_code` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产班组',
  `mod_file` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '变更附件',
  `sort` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '序号',
  `mod_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '变更类型0=正常,1=已变更,2=已取消,3=已暂停,4=已恢复',
  `org_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门',
  `line_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '产线编码',
  `sale_order_sub_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '销售订单行号',
  `bom_ver` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `drawing_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '图号',
  `produce_plan_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划id',
  `crm_order_quantity` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单数量',
  `quantity` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单数量',
  `shipment_quantity` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货数量',
  `completed_quantity` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '完工数量',
  `unit_price` decimal(10,2) DEFAULT NULL COMMENT '单价',
  `amount` decimal(10,2) DEFAULT NULL COMMENT '总金额',
  `cust_need` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '客户特殊需求',
  `need_dt` date DEFAULT NULL,
  `design_dt` date DEFAULT NULL,
  `procure_dt` date DEFAULT NULL,
  `machining_dt` date DEFAULT NULL,
  `produce_plan_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编号',
  `scheduled_qty` decimal(10,2) DEFAULT NULL COMMENT '已排产数量',
  `route_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工艺编码',
  `plan_start_dt` date DEFAULT NULL COMMENT '计划开工日期',
  `plan_end_dt` date DEFAULT NULL COMMENT '计划完工日期',
  `act_hour` decimal(10,2) DEFAULT NULL COMMENT '实际工时',
  `rated_hour` decimal(10,2) DEFAULT NULL COMMENT '额定工时',
  `define1` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '自定义项1',
  `rep_qty` decimal(10,2) DEFAULT NULL COMMENT '报工数量',
  `act_start_time` datetime DEFAULT NULL COMMENT '实际开工时间',
  `act_rep_time` datetime DEFAULT NULL COMMENT '实际报工时间',
  `product_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产品编码',
  `carry_st` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '10' COMMENT '执行状态：10待执行、20执行中、30已执行',
  `sale_order_sub_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单明细ID',
  `sale_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单编码',
  `order_st` varchar(10) DEFAULT NULL COMMENT '状态：10-正常 20-暂停中',
  `aps_plan_sub_id` bigint DEFAULT NULL COMMENT '物料需求计划子表id',
  `bsn_type` varchar(50) DEFAULT NULL COMMENT '业务类型:10正常,20预投,30代工,40样品,50备货',
  `aux_unit` varchar(50) DEFAULT NULL COMMENT '生产单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '生产数量',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_line_code_single` (`line_code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_mid_single` (`mid`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_produce_plan_id_single` (`produce_plan_id`),
  KEY `idx_sale_order_sub_code_single` (`sale_order_sub_code`),
  KEY `idx_team_code_single` (`team_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='生产订单明细';

-- mes_production_plan
CREATE TABLE `mes_production_plan` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'id',
  `book_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '编码',
  `sale_order_code` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '销售订单编码',
  `org_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门',
  `plan_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '计划员',
  `status` tinyint DEFAULT NULL COMMENT '流程状态:0草稿,1审核中,2已通过,3已驳回,4撤回,5终止',
  `crt_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `upd_tm` datetime DEFAULT NULL COMMENT '更新时间',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `plan_dt` date DEFAULT NULL,
  `change_st` varchar(10) COLLATE utf8mb4_general_ci DEFAULT '10' COMMENT '变更状态:10正常20锁定30已变更40终止',
  `lock_src_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '上游变更申请id',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_tm_single` (`crt_tm`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_lock_src_id_single` (`lock_src_id`),
  KEY `idx_org_code_single` (`org_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='生产计划';

-- mes_production_plan_sub
CREATE TABLE `mes_production_plan_sub` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'id',
