  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `upd_tm` datetime DEFAULT NULL COMMENT '更新时间',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `carry_st` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '执行状态 10:待执行、20:执行中、30已执行',
  `act_com_time` datetime DEFAULT NULL COMMENT '实际结束时间',
  `sale_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '销售订单编码',
  `current_inventory` decimal(10,2) DEFAULT NULL COMMENT '当前库存',
  `expect_inventory` decimal(10,2) DEFAULT NULL COMMENT '预计库存',
  `rqm_qty` decimal(10,2) DEFAULT NULL COMMENT '需求数量',
  `priority` varchar(5) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '优先级',
  `full_tank_qty` decimal(10,2) DEFAULT NULL COMMENT '整缸量',
  `bom_ver` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `bom_type` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源bom(10:技术BOM 20:生产BOM)',
  `bsn_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务类型（字典值：10正常、20预投、30代工、40样品）',
  `aux_unit` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生产单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '生产数量',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_tm_single` (`crt_tm`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_mid_single` (`mid`),
  KEY `idx_sale_order_code_single` (`sale_order_code`),
  KEY `idx_sale_sub_id_single` (`sale_sub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='生产计划子表';

-- mes_production_plan_sub_extend
CREATE TABLE `mes_production_plan_sub_extend` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
