-- mes_report_hour
CREATE TABLE `mes_report_hour` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '报工工时编号',
  `oprl_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '作业人',
  `report_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '报工单编码',
  `job_task_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '作业任务单编码',
  `wrk_hour` decimal(10,2) DEFAULT NULL COMMENT '工时(分钟)',
  `check_st` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核状态',
  `check_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '审核人',
  `check_tm` datetime DEFAULT NULL COMMENT '审核时间',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `upd_tm` datetime DEFAULT NULL COMMENT '修改时间',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注',
  `status` varchar(5) DEFAULT NULL COMMENT '审批流：0草稿,1审核中,2已通过,3已驳回,4已撤回,5已终止\r\n状态切换：0草稿,1待审核,2已审核',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_job_task_code_single` (`job_task_code`),
  KEY `idx_report_order_code_single` (`report_order_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='工时统计';

-- mes_report_order
CREATE TABLE `mes_report_order` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '报工单编号',
  `prod_pln_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产计划行号',
  `mate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编号',
  `rpt_qty` decimal(10,2) DEFAULT '0.00' COMMENT '报工数量',
  `plant_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '加工设备',
  `team_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '所属班组',
  `check_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '检验状态:10=未检验,20=已检验',
  `stn_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工位',
  `rgon_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '车间',
  `rpt_uid` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '报工人',
  `check_tm` datetime DEFAULT NULL COMMENT '检验时间',
  `check_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '质检员',
  `pcs_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工序名称',
  `start_tm` datetime DEFAULT NULL COMMENT '开始时间',
  `end_tm` datetime DEFAULT NULL COMMENT '结束时间/完工时间',
  `piece_rate` decimal(8,2) DEFAULT NULL COMMENT '工资/件',
  `bill_src` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '单据来源:10作业任务单20返工单',
  `prod_order_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '作业号(生产工单行号)',
  `check_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '检验类型0=无需检验,1=过程检验,2=入库检验,3=来料检验',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `upd_tm` datetime DEFAULT NULL COMMENT '修改时间',
  `mod_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '变更类型',
  `elig_qty` decimal(10,2) DEFAULT NULL COMMENT '合格量',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '部门',
  `ispt_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '质检方案',
  `wrk_hour` decimal(10,2) DEFAULT NULL COMMENT '工时(H)',
  `drawing_number` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '图号',
  `self_crt` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '创建者',
  `self_crt_tm` datetime DEFAULT NULL COMMENT '创建日期',
  `production_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编号',
  `prod_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产工单编码',
  `sale_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单编码',
  `team_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '报工班组',
  `order_tm` datetime DEFAULT NULL COMMENT '报工时间',
  `status` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '状态10=未生成,20=已生成',
  `sort` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '排序号',
  `bill_src_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '来源单据号',
  `line_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '产线编码',
  `oprl_uid` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '作业人',
  `rated_hour` decimal(10,2) DEFAULT '0.00' COMMENT '额定工时',
  `average_hour` decimal(10,2) DEFAULT NULL COMMENT '平均工时',
  `act_hour` decimal(10,2) DEFAULT '0.00' COMMENT '实际工时',
  `rpt_total_hour` decimal(10,2) DEFAULT NULL COMMENT '总工时',
  `batch_no` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '批次号',
  `is_inspection` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '0' COMMENT '是否报检  0:否 1:是',
  `aux_unit` varchar(50) DEFAULT NULL COMMENT '生产单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '生产数量',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_ispt_code_single` (`ispt_code`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_pcs_code_single` (`pcs_code`),
  KEY `idx_plant_code_single` (`plant_code`),
  KEY `idx_prod_order_code_single` (`prod_order_code`),
  KEY `idx_prod_order_sub_code_single` (`prod_order_sub_code`),
  KEY `idx_prod_pln_sub_code_single` (`prod_pln_sub_code`),
  KEY `idx_production_order_code_single` (`production_order_code`),
  KEY `idx_rgon_code_single` (`rgon_code`),
  KEY `idx_sale_order_code_single` (`sale_order_code`),
  KEY `idx_stn_code_single` (`stn_code`),
  KEY `idx_team_code_single` (`team_code`),
  KEY `idx_team_id_single` (`team_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='报工单';

