  `welding_hour` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '焊接工时',
  `laser_welding_hour` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '激光焊接工时',
  `wire_drawing_grinding_hour` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '拉丝打磨工时',
  `painting_hour` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '喷涂工时',
  `total_hours` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '工时合计',
  PRIMARY KEY (`Id`,`book_id`) USING BTREE,
