  KEY `idx_md_mate_info_code_single` (`md_mate_info_code`),
  KEY `idx_md_mate_info_id_single` (`md_mate_info_id`),
  KEY `idx_md_team_id_single` (`md_team_id`),
  KEY `idx_mes_product_order_code_single` (`mes_product_order_code`),
  KEY `idx_mes_report_order_id_single` (`mes_report_order_id`),
  KEY `idx_produce_order_code_single` (`produce_order_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='报工单子表';

