  `fare` decimal(10,2) DEFAULT NULL COMMENT '运费',
  `order_src` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '订单来源:10=生成20=新增',
  `send_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货人',
  `rcvd_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '收料状态:10=未收料,15=部分收料,20=已收料',
  `rcvd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '收料人',
  `rcvd_tm` datetime DEFAULT NULL COMMENT '收料时间',
  `org_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货部门',
  `status` tinyint DEFAULT NULL COMMENT '流程状态:0草稿,1审核中,2已通过,3已驳回',
  `order_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '订单类型',
  `car_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '车辆名称',
  `car_weight` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '车辆重量',
  `km_number` decimal(11,2) DEFAULT NULL COMMENT '公里数',
  `car_picture` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '车辆图片',
  `send_unit` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货单位',
  `snd_tm` datetime DEFAULT NULL COMMENT '发货日期',
  `md_cust_info_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '收货单位',
  `total_amount` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '合计金额',
  `receive_addr` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '收货地址',
  `ctc_tel` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '联系电话',
  `Send_addr` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货地址',
  `logi_order` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物流单号',
  `carry_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '承运人',
  `rqs_snd_tm` datetime DEFAULT NULL COMMENT '要求发货日期',
  `order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '订单编码',
  `act_pymt_sita` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '实际付款情况',
  `snd_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货类别',
  `due_tm` datetime DEFAULT NULL COMMENT '应付款日期',
  `snd_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货状态：0未发货1已发货',
  `mes_produce_plan_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `make_pick` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `make_si` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `cust_confirm_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '客户订单确认编码',
  `cust_send_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '客户方送货编码',
  `urgent_level` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '紧急程度:10一般、20紧急、30非常紧急',
  `carry_st` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '执行状态：10待执行、20执行中、30已执行、40已挂起、50已关闭',
  `check_uid` varchar(50) DEFAULT NULL COMMENT '审核人',
  `check_tm` datetime DEFAULT NULL COMMENT '审核时间',
  `is_ispt` varchar(10) DEFAULT NULL COMMENT '是否报检 10 未报检 20 已报检',
  `ispt_uid` varchar(50) DEFAULT NULL COMMENT '报检人',
  `ispt_tm` datetime DEFAULT NULL COMMENT '报检时间',
  `attachment` varchar(2000) DEFAULT NULL COMMENT '签收单附件',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_car_code_single` (`car_code`),
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_cust_code_single` (`cust_code`),
  KEY `idx_logi_code_single` (`logi_code`),
  KEY `idx_logi_no_single` (`logi_no`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_sale_order_code_single` (`sale_order_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='发货单';

-- mes_send_order_sub
CREATE TABLE `mes_send_order_sub` (
  `id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '10' COMMENT '主键',
  `book_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '账套id',
  `mid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货单id',
  `code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货单行号',
  `mate_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编码',
  `unit_wght` decimal(10,2) DEFAULT NULL COMMENT '单重(KG)',
  `send_qty` decimal(10,2) DEFAULT NULL COMMENT '发货数量',
  `total_wght` decimal(10,2) DEFAULT NULL COMMENT '总重量(KG)',
  `remarks` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '备注',
  `crt_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '下单人',
  `crt_tm` datetime DEFAULT NULL COMMENT '下单时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '修改人',
  `upd_tm` datetime DEFAULT NULL COMMENT '修改时间',
  `unit_prc` decimal(10,2) DEFAULT NULL COMMENT '订单单价',
  `sale_order_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单行号',
  `rcvded_qty` decimal(10,2) DEFAULT NULL COMMENT '已收料数量',
  `prod_pln_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `flag` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '标识：补料10、领料20、正常30',
  `make_st` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '领料补料出库状态：未生成10、部分生成20、已生成30',
  `picked_qty` decimal(10,2) DEFAULT NULL COMMENT '已领料数量',
  `produce_plan_sub_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '生产订单子表行号',
  `mes_send_order_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货单id',
  `md_mate_info_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料id',
  `md_mate_info_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料编码',
  `md_mate_info_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料名称',
  `spec_type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '物料规格',
  `unit` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '计量单位',
  `unit_kg` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '单重(KG)',
  `send_msr` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '数量',
  `unit_price` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '单价',
  `amount` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '金额',
  `total_msr` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '总重量(KG)',
  `spl_flag` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `production_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生产订单编码',
  `pd_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '父产品编码',
  `pd_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `prch_order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '采购订单编码',
  `sale_order_sub_id` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '销售订单子表id',
  `send_task_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '发货任务编码',
  `order_type` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '订单类型 10发货任务、20客户订单、30销售订单、40售后订单',
  `order_code` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '订单编码',
  `size` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '尺寸',
  `pack_spec` varchar(50) DEFAULT NULL COMMENT '包装规格',
  `piece` decimal(10,2) DEFAULT NULL COMMENT '件数',
  `src_order_id` varchar(50) DEFAULT NULL COMMENT '来源单据id',
  `src_order_type` varchar(5) DEFAULT NULL COMMENT '来源类型',
  `src_order_code` varchar(50) DEFAULT NULL COMMENT '来源单据编码',
  `qualified_qty` decimal(18,4) DEFAULT NULL COMMENT '合格数量',
  `aux_unit` varchar(50) DEFAULT NULL COMMENT '销售单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '销售数量',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `prch_order_code_bookid` (`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_md_mate_info_code_single` (`md_mate_info_code`),
  KEY `idx_md_mate_info_id_single` (`md_mate_info_id`),
  KEY `idx_mes_send_order_id_single` (`mes_send_order_id`),
  KEY `idx_mid_single` (`mid`),
  KEY `idx_pd_code_single` (`pd_code`),
  KEY `idx_prch_order_code_single` (`prch_order_code`),
  KEY `idx_prod_pln_code_single` (`prod_pln_code`),
  KEY `idx_produce_plan_sub_code_single` (`produce_plan_sub_code`),
  KEY `idx_production_order_code_single` (`production_order_code`),
  KEY `idx_sale_order_sub_code_single` (`sale_order_sub_code`),
  KEY `idx_sale_order_sub_id_single` (`sale_order_sub_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='发货单子表';

-- mes_send_task
CREATE TABLE `mes_send_task` (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'id',
  `book_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账套id',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发货任务编码',
  `carry_st` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '执行状态 10:待执行、20:执行中、30已执行',
  `require_dt` date DEFAULT NULL COMMENT '要货日期',
  `mate_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '产品编码',
  `qty` decimal(10,2) DEFAULT NULL COMMENT '基准数量',
  `apply_qty` decimal(10,2) DEFAULT '0.00' COMMENT '申请数量',
  `send_qty` decimal(10,2) DEFAULT '0.00' COMMENT '发货数量',
  `inr_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '内勤',
  `executed_tm` datetime DEFAULT NULL COMMENT '发货完成时间',
  `src_order_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源单据号',
  `src_order_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源单据类型 10:新增 20:销售订单 30:客户订单 40:售后单',
  `src_order_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '来源单据id',
  `org_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门',
  `cust_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户',
  `crt_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `crt_tm` datetime DEFAULT NULL COMMENT '创建时间',
  `upd_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改人',
  `upd_tm` datetime DEFAULT NULL COMMENT '修改时间',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `send_end_dt` date DEFAULT NULL,
  `pack_spec` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '包装规格',
  `piece` decimal(10,2) DEFAULT NULL COMMENT '件数',
  `unit_prc` decimal(10,2) DEFAULT NULL COMMENT '订单单价',
  `unit_wght` decimal(10,2) DEFAULT NULL COMMENT '单重',
  `change_st` varchar(10) COLLATE utf8mb4_general_ci DEFAULT '10' COMMENT '变更状态:10正常20锁定30已变更40终止',
  `aux_unit` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '销售单位',
  `aux_qty` decimal(10,2) DEFAULT NULL COMMENT '销售数量',
  `lock_src_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '上游变更申请id',
  PRIMARY KEY (`id`,`book_id`) USING BTREE,
  KEY `idx_code_single` (`code`),
  KEY `idx_crt_uid_single` (`crt_uid`),
  KEY `idx_cust_code_single` (`cust_code`),
  KEY `idx_lock_src_id_single` (`lock_src_id`),
  KEY `idx_mate_code_single` (`mate_code`),
  KEY `idx_org_code_single` (`org_code`),
  KEY `idx_src_order_code_single` (`src_order_code`),
  KEY `idx_src_order_id_single` (`src_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='发货任务';
